arguments.commandText:
perl -0777 -pe "s/        _Cycle\('void-settings-screen', 'screen', labelFor\(cfg.type\), cycleScreen\),/        _Cycle('void-settings-screen', 'screen', labelFor(cfg.type), cycleScreen),
        if (cfg is CassetteScreenConfig) _Cycle(
            'void-settings-cassette-variant',
            'color scheme',
            cassetteVariantMeta[cfg.variant]!.label,
            () {
              final next = CassetteVariant.values\[(cfg.variant.index + 1) % CassetteVariant.values.length\];
              settings.saveScreenConfig(cfg.copyWith(variant: next));
            },
          ),/s" lib/widgets/void_settings_sheet.dart -i && echo DONE; tail -n +386 lib/widgets/void_settings_sheet.dart | head -n 40

